script:
const root=root_element;const el=root.querySelector(".pmo-b");
const T=(typeof __==="function")?__:(s)=>s;
const esc=(s)=>s==null?"":String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const nz=(v)=>(v===null||v===undefined||v==="")?"–":v;
const hpill={on_track:"ok",at_risk:"warn",deviated:"bad"};
function fail(){el.innerHTML=`<div class="empty">${esc(T("Could not load this PMO panel."))}</div>`;}

function customers(rows){
  if(!rows||!rows.length) return `<div class="empty">${esc(T("No customer-linked projects."))}</div>`;
  let h=`<div class="wrap"><table><thead><tr>
    <th>${esc(T("Customer"))}</th><th class="num">${esc(T("Active projects"))}</th>
    <th class="num">${esc(T("At risk / deviated"))}</th><th class="num">${esc(T("Planned/Actual (h)"))}</th>
  </tr></thead><tbody>`;
  for(const r of rows){
    h+=`<tr><td><b>${esc(r.customer)}</b></td><td class="num">${nz(r.projects)}</td>
      <td class="num ${(r.at_risk_deviated>0)?'bad':''}">${nz(r.at_risk_deviated)}</td>
      <td class="num">${nz(Math.round(r.planned))} / ${nz(Math.round(r.actual))}</td></tr>`;
  }
  return h+`</tbody></table></div>`;
}
frappe.xcall("pmo.dashboard.customers_block").then((d)=>{el.innerHTML=customers(d.customers);}).catch((e)=>{fail();console.error("PMO customers",e);});

const root=root_element;const el=root.querySelector(".pmo-g");
const T=(typeof __==="function")?__:(s)=>s;
const esc=(s)=>s==null?"":String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
function fail(){el.innerHTML=`<div class="empty">${esc(T("Could not load this PMO panel."))}</div>`;}
function kpi(v,l){return `<div class="kpi"><div class="v">${esc(v??0)}</div><div class="l">${esc(l)}</div></div>`;}
function counts(c){
  return `<div class="counts">`
    +kpi(c.without_handoff,T("Without Handoff"))
    +kpi(c.needs_baseline,T("Without baseline"))
    +kpi(c.open_change_requests,T("Open change requests"))
    +kpi(c.needs_closure,T("Require closure"))
    +kpi(c.needs_review,T("Require review"))
    +`<div class="kpi muted"><div class="v">—</div><div class="l">${esc(T("Risk analysis"))}</div><div class="sub">${esc(T("Pending implementation"))}</div></div>`
    +`</div>`;
}
function items(rows){
  if(!rows||!rows.length) return `<div class="empty">${esc(T("No pending governance actions."))}</div>`;
  let h="";
  for(const r of rows){
    let chips="";
    for(const a of (r.actions||[])) chips+=`<span class="chip warn">${esc(a)}</span>`;
    h+=`<div class="row" data-project="${esc(r.project)}"><span class="pname">${esc(r.project_name||r.project)}</span>`
      +`${r.customer?`<span class="lc">· ${esc(r.customer)}</span>`:""}`
      +`<div class="chips">${chips}</div></div>`;
  }
  return h;
}
el.addEventListener("click",(e)=>{const pr=e.target.closest("[data-project]");if(pr){frappe.set_route("pmo_project_control",pr.getAttribute("data-project"));}});
frappe.xcall("pmo.dashboard.governance_block").then((d)=>{
  const g=d.governance||{};
  el.innerHTML=counts(g.counts||{})+`<h3>${esc(T("Pending governance actions"))}</h3>`+items(g.items);
}).catch((e)=>{fail();console.error("PMO governance",e);});
